 useEffect(()=>{if(!session||!supabase)return;let cancelled=false;(async()=>{const [a,c]=await Promise.all([supabase.rpc('my_pos_access'),supabase.rpc('my_waiter_counters')]);if(cancelled)return;if(a.error){setError(a.error.message);return;}setAccess(a.data);setCounters(c.error?[]:c.data||[]);if(a.data?.active){const isAdmin=a.data.roles?.some(r=>r.role==='director_admin'||r.role==='central_manager');const isWaiter=a.data.roles?.some(r=>r.department==='Hotel'&&['waiter','head_waiter','order_taker'].includes(r.role));setLoginChannel(isAdmin?'admin':'staff');if(isAdmin&&new URLSearchParams(window.location.search).get('section')==='hotel-settings')loadHotelCounters();if(!isAdmin)setSection(isWaiter?'Restaurant':a.data.roles?.some(r=>r.role==='kitchen_staff')?'Kitchen Queue':a.data.roles?.some(r=>r.role==='bar_staff')?'Bar Queue':a.data.roles?.some(r=>r.role==='cashier')?'Cashier Shifts':'Dashboard');}const [products,unpaid]=await Promise.all([supabase.rpc('hotel_menu'),supabase.rpc('my_cashier_hotel_orders')]);if(!cancelled){setMenu(products.data||[]);setOrders(unpaid.data||[]);const {data:ready}=await supabase.rpc('my_waiter_ready_tickets');if(!cancelled)setReadyTickets(ready||[]);}if(a.data?.roles?.some(r=>['director_admin','central_manager'].includes(r.role)||(r.department==='Hotel'&&['department_manager','supervisor'].includes(r.role)))){const dash=await supabase.rpc('hotel_admin_dashboard');if(!cancelled){if(dash.error)setError(dash.error.message);else setDashboard(dash.data)}}if(c.error)setError(c.error.message)})();return()=>{cancelled=true}},[session]);
 async function signIn(e){e.preventDefault();setBusy(true);setError('');if(loginChannel==='staff'){if(!/^[a-z][a-z0-9._-]{2,31}$/.test(email.trim().toLowerCase())||!/^[0-9]{5}$/.test(password)){setError('Enter your staff username and five-digit PIN.');setBusy(false);return;}const{data,error:err}=await supabase.functions.invoke('mwisho-username-login',{body:{username:email.trim().toLowerCase(),password}});if(err||data?.error){let m=data?.error||'Unable to sign in';if(err?.context)try{m=(await err.context.json()).error||m}catch{}setError(m)}else{const{error:sessionError}=await supabase.auth.setSession({access_token:data.access_token,refresh_token:data.refresh_token});if(sessionError)setError(sessionError.message)}}else{if(!email.trim().includes('@'))setError('Enter the Director/Admin email.');else{const{error:err}=await supabase.auth.signInWithPassword({email:email.trim(),password});if(err)setError(err.message)}}setBusy(false)}
 async function requestPasswordReset(){const address=passwordResetEmail.trim();if(!/^\S+@\S+\.\S+$/.test(address)){setError('Enter your registered email address.');return;}setBusy(true);setError('');const{error:err}=await supabase.auth.resetPasswordForEmail(address,{redirectTo:window.location.origin+window.location.pathname});if(err)setError(err.message);else setResetEmailSent(true);setBusy(false)}
 async function saveNewPassword(e){e.preventDefault();setError('');if(newPassword.length<12){setError('Use at least 12 characters.');return;}if(newPassword!==confirmPassword){setError('Passwords do not match.');return;}if(!session){setError('Recovery link invalid or expired. Request a new one.');return;}setBusy(true);const{error:err}=await supabase.auth.updateUser({password:newPassword});if(err)setError(err.message);else{setRecovery(false);setNewPassword('');setConfirmPassword('');await supabase.auth.signOut();setSession(null);setNotice('Password changed. Sign in with your new password.');window.history.replaceState(null,'',window.location.pathname)}setBusy(false)}
