 if(!session)return <div className="center"><div className="login"><h1>MWISHO</h1><p>{loginChannel==='staff'?'Staff POS Login':'Administration / Control Center'}</p><div className="login-channel-switch"><button type="button" className={loginChannel==='staff'?'primary':''} onClick={()=>{setLoginChannel('staff');setError('');setEmail('');setPassword('');setShowPasswordReset(false);window.history.replaceState(null,'',window.location.pathname+'?portal=staff')}}>Staff POS</button><button type="button" className={loginChannel==='admin'?'primary':''} onClick={()=>{setLoginChannel('admin');setError('');setEmail('');setPassword('');setShowPasswordReset(false);window.history.replaceState(null,'',window.location.pathname+'?portal=admin')}}>Admin Login</button></div>{showPasswordReset?<form onSubmit={e=>{e.preventDefault();requestPasswordReset()}}><h2>Reset password</h2><p>Enter the email address registered by management for your staff account.</p><label>Registered email address<input type="email" required autoComplete="email" value={passwordResetEmail} onChange={e=>setPasswordResetEmail(e.target.value)}/></label>{error&&<p role="alert" className="error">{error}</p>}{resetEmailSent&&<p role="status">If this account exists, check its inbox for the password reset link.</p>}<button className="primary" type="submit" disabled={busy}>{busy?'Sending…':'Send password reset link'}</button><button type="button" onClick={()=>{setShowPasswordReset(false);setError('');setResetEmailSent(false)}}>Back to sign in</button></form>:<form onSubmit={signIn}><label>{loginChannel==='staff'?'Staff Username':'Admin Email'}<input type="text" value={email} onChange={e=>setEmail(e.target.value)} required autoCapitalize="none" autoComplete="username"/></label><label>{loginChannel==='staff'?'Five-digit Staff PIN':'Admin Password'}<input type="password" value={password} onChange={e=>setPassword(loginChannel==='staff'?e.target.value.replace(/\D/g,'').slice(0,5):e.target.value)} required inputMode={loginChannel==='staff'?'numeric':'text'} maxLength={loginChannel==='staff'?5:undefined} autoComplete="current-password"/></label>{error&&<p role="alert" className="error">{error}</p>}{notice&&<p role="status">{notice}</p>}<button className="primary" disabled={busy}>{busy?'Signing in…':'Sign in'}</button>{loginChannel==='admin'&&<button type="button" disabled={busy} onClick={()=>{setShowPasswordReset(true);setError('');setResetEmailSent(false)}}>Forgot Admin password?</button>}<small>Ordinary staff use a five-digit PIN. Ask Admin to reset a forgotten staff PIN.</small></form>}</div></div>;
 if(session?.user?.user_metadata?.pin_login&&session?.user?.user_metadata?.must_change_pin)return <div className="center"><form className="login" onSubmit={async e=>{e.preventDefault();if(!/^\d{5}$/.test(pinCurrent)||!/^\d{5}$/.test(pinNew)||pinNew!==pinConfirm||pinNew===pinCurrent){setError('Enter a five-digit current PIN and a different matching five-digit new PIN.');return;}setBusy(true);setError('');const{data,error:err}=await supabase.functions.invoke('mwisho-change-pin',{body:{current_pin:pinCurrent,new_pin:pinNew}});if(err||data?.error){let m=data?.error||err?.message||'Could not change PIN';if(err?.context)try{m=(await err.context.json()).error||m}catch{}setError(m)}else{setPinCurrent('');setPinNew('');setPinConfirm('');setPassword('');await supabase.auth.signOut();setNotice('PIN changed. Sign in using your new PIN.')}setBusy(false)}}><h2>Change Temporary PIN</h2><p>Enter the temporary PIN given to you by Admin, then create a new five-digit PIN before using the POS.</p><label>Temporary PIN<input required type="password" inputMode="numeric" maxLength={5} pattern="[0-9]{5}" value={pinCurrent} onChange={e=>setPinCurrent(e.target.value.replace(/\D/g,'').slice(0,5))}/></label><label>New five-digit PIN<input required type="password" inputMode="numeric" maxLength={5} pattern="[0-9]{5}" value={pinNew} onChange={e=>setPinNew(e.target.value.replace(/\D/g,'').slice(0,5))}/></label><label>Confirm new PIN<input required type="password" inputMode="numeric" maxLength={5} pattern="[0-9]{5}" value={pinConfirm} onChange={e=>setPinConfirm(e.target.value.replace(/\D/g,'').slice(0,5))}/></label>{error&&<p role="alert" className="error">{error}</p>}<button className="primary" disabled={busy}>Save new PIN</button><button type="button" onClick={signOut}>Sign out</button></form></div>;
