{tabs.filter(t=>['Dashboard','Menu Management','Cancellation Approvals','Invoice Approvals','Complimentary Approvals','Staff Bills / Debts'].includes(t)).map(t=><button key={t} className={section===t?'selected':''} onClick={()=>navigate(t)}><span className="menu-icon" aria-hidden="true">{operationIcons[t]||'✦'}</span><span className="menu-label">{t==='Dashboard'?'Management Dashboard':t}</span><span className="menu-chevron" aria-hidden="true">›</span></button>)}
